(function () {
  'use strict';
  // Guided time value of money for savings: monthly periods, deposits at the end of each month,
  // monthly compounding at annual rate / 12. Solves for FV, PMT, N, PV (closed form) or the rate (bisection).
  //   FV = PV(1+i)^n + PMT((1+i)^n - 1)/i            PMT = (FV - PV(1+i)^n) i / ((1+i)^n - 1)
  //   PV = (FV - PMT((1+i)^n - 1)/i) / (1+i)^n         n = ln((FV i + PMT)/(PV i + PMT)) / ln(1+i)
  // Checked under Node (scratchpad/tests/b7basic/bf_test.js) against closed-form references:
  // $100/month at 6% for 30 years = $100,451.50; $10,000 at 5% monthly for 10 years = $16,470.09;
  // $286.45/month reaches $1,000,000 in 40 years at 8%; $54,963.27 today grows to $100,000 in 10 years at 6%.
  // Round trips (FV -> PMT, PV, N, rate) return the starting inputs; 0% rate handled separately.
  // ---- Time value of money, monthly periods, deposits at the end of each month ----
  var MAX_MONTHS = 1200; // 100 years

  function fvOf(pv, pmt, i, n) {
    if (i === 0) return pv + pmt * n;
    var g = Math.pow(1 + i, n);
    return pv * g + pmt * (g - 1) / i;
  }

  function pmtFor(fv, pv, i, n) {
    if (n <= 0) return NaN;
    if (i === 0) return (fv - pv) / n;
    var g = Math.pow(1 + i, n);
    return (fv - pv * g) * i / (g - 1);
  }

  function pvFor(fv, pmt, i, n) {
    if (i === 0) return fv - pmt * n;
    var g = Math.pow(1 + i, n);
    return (fv - pmt * (g - 1) / i) / g;
  }

  // Months (fractional) until the balance reaches fv; Infinity if it never does.
  function nFor(fv, pv, pmt, i) {
    if (pv >= fv) return 0;
    if (i === 0) return pmt > 0 ? (fv - pv) / pmt : Infinity;
    var num = fv * i + pmt, den = pv * i + pmt;
    if (den <= 0) return Infinity;
    return Math.log(num / den) / Math.log(1 + i);
  }

  // Annual rate (decimal, compounded monthly) that grows pv + pmt into fv over n months.
  // Returns 0 if no growth is needed, NaN if more than 100% a year would be required.
  function rateFor(fv, pv, pmt, n) {
    if (fvOf(pv, pmt, 0, n) >= fv) return 0;
    var lo = 0, hi = 1;
    if (fvOf(pv, pmt, hi / 12, n) < fv) return NaN;
    for (var k = 0; k < 200; k++) {
      var mid = (lo + hi) / 2;
      if (fvOf(pv, pmt, mid / 12, n) < fv) lo = mid; else hi = mid;
      if (hi - lo < 1e-12) break;
    }
    return (lo + hi) / 2;
  }

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  var pct = new Intl.NumberFormat('en-US', { maximumFractionDigits: 2 });

  var LABELS = { fv: 'You will have', pmt: 'Save each month', n: 'Time to reach your goal', pv: 'Put in today', rate: 'Return you need' };
  // Which input each question hides (it is the answer).
  var HIDE = { fv: 'bfFieldFv', pmt: 'bfFieldPmt', n: 'bfFieldYears', pv: 'bfFieldPv', rate: 'bfFieldRate' };

  function num(id) { var v = parseFloat(document.getElementById(id).value); return isNaN(v) ? NaN : v; }
  function set(id, text) { document.getElementById(id).textContent = text; }

  function duration(months) {
    var y = Math.floor(months / 12), m = months % 12, parts = [];
    if (y) parts.push(y + (y === 1 ? ' year' : ' years'));
    if (m || !y) parts.push(m + (m === 1 ? ' month' : ' months'));
    return parts.join(' ');
  }

  function question() {
    var checked = document.querySelector('input[name="bfQuestion"]:checked');
    return checked ? checked.value : 'fv';
  }

  function showFields(q) {
    ['bfFieldPv', 'bfFieldPmt', 'bfFieldFv', 'bfFieldRate', 'bfFieldYears'].forEach(function (id) {
      document.getElementById(id).hidden = HIDE[q] === id;
    });
  }

  function clearResults(msg) {
    var error = document.getElementById('bfError');
    error.textContent = msg; error.hidden = false;
    ['bfAnswer', 'bfOutPv', 'bfOutPmt', 'bfOutTime', 'bfOutRate', 'bfOutIn', 'bfOutGrowth', 'bfOutFv'].forEach(function (id) { set(id, '–'); });
    set('bfSentence', '');
    var body = document.getElementById('bfSchedule');
    while (body.firstChild) body.removeChild(body.firstChild);
  }

  function update() {
    var q = question();
    showFields(q);
    set('bfAnswerLabel', LABELS[q]);
    var pv = num('bfPv'), pmt = num('bfPmt'), fv = num('bfFv'), ratePct = num('bfRate'), years = num('bfYears');
    var needs = { pv: q !== 'pv', pmt: q !== 'pmt', fv: q !== 'fv', rate: q !== 'rate', years: q !== 'n' };
    var bad = (needs.pv && (isNaN(pv) || pv < 0)) || (needs.pmt && (isNaN(pmt) || pmt < 0)) ||
              (needs.fv && (isNaN(fv) || fv <= 0)) || (needs.rate && (isNaN(ratePct) || ratePct < 0 || ratePct > 50)) ||
              (needs.years && (isNaN(years) || years <= 0 || years > 100));
    if (bad) {
      clearResults('Enter amounts of 0 or more, a goal above 0, a return from 0 to 50% and a time from 1 month to 100 years.');
      return;
    }
    if ((q === 'n' || q === 'rate') && pv === 0 && pmt === 0) {
      clearResults('Enter an amount you have now, a monthly saving, or both.');
      return;
    }
    document.getElementById('bfError').hidden = true;

    var i = needs.rate ? ratePct / 100 / 12 : 0;
    var months = needs.years ? Math.max(1, Math.round(years * 12)) : 0;
    var sentence = '', answer = '', rateUsed = needs.rate ? ratePct / 100 : 0;
    var rateText = function (r) { return pct.format(r * 100) + '%'; };

    if (q === 'fv') {
      fv = fvOf(pv, pmt, i, months);
      answer = money.format(fv);
      sentence = 'Starting with ' + money0.format(pv) + ' and saving ' + money.format(pmt) + ' a month at ' + rateText(rateUsed) +
        ' a year, you will have about ' + money.format(fv) + ' after ' + duration(months) + '.';
    } else if (q === 'pmt') {
      var p = pmtFor(fv, pv, i, months);
      if (p <= 0) {
        pmt = 0;
        answer = money.format(0);
        sentence = 'Your ' + money0.format(pv) + ' alone grows to ' + money.format(fvOf(pv, 0, i, months)) + ' in ' + duration(months) +
          ' at ' + rateText(rateUsed) + ' a year, which already reaches your ' + money0.format(fv) + ' goal. No monthly saving is needed.';
      } else {
        pmt = p;
        answer = money.format(p);
        sentence = 'To grow ' + money0.format(pv) + ' into ' + money0.format(fv) + ' in ' + duration(months) + ' at ' + rateText(rateUsed) +
          ' a year, save about ' + money.format(p) + ' a month.';
      }
    } else if (q === 'n') {
      var nf = nFor(fv, pv, pmt, i);
      if (!isFinite(nf) || nf > MAX_MONTHS) {
        clearResults('At this rate and saving amount the goal takes more than 100 years. Try saving more or a higher return.');
        return;
      }
      months = Math.ceil(nf - 1e-9);
      if (months === 0) {
        answer = 'Already there';
        sentence = 'You already have ' + money0.format(pv) + ', which meets your ' + money0.format(fv) + ' goal.';
      } else {
        answer = duration(months);
        sentence = 'Saving ' + money.format(pmt) + ' a month on top of ' + money0.format(pv) + ' at ' + rateText(rateUsed) +
          ' a year, you pass ' + money0.format(fv) + ' after about ' + duration(months) + '.';
      }
    } else if (q === 'pv') {
      var need = pvFor(fv, pmt, i, months);
      if (need <= 0) {
        pv = 0;
        answer = money.format(0);
        sentence = 'Saving ' + money.format(pmt) + ' a month at ' + rateText(rateUsed) + ' a year reaches ' + money.format(fvOf(0, pmt, i, months)) +
          ' in ' + duration(months) + ', which already meets your ' + money0.format(fv) + ' goal. You don’t need a lump sum.';
      } else {
        pv = need;
        answer = money.format(need);
        sentence = 'To reach ' + money0.format(fv) + ' in ' + duration(months) + ' while saving ' + money.format(pmt) + ' a month at ' +
          rateText(rateUsed) + ' a year, you need about ' + money.format(need) + ' today.';
      }
    } else {
      var r = rateFor(fv, pv, pmt, months);
      if (isNaN(r)) {
        clearResults('Reaching this goal would need a return above 100% a year. Allow more time, save more, or lower the goal.');
        return;
      }
      rateUsed = r; i = r / 12;
      answer = rateText(r) + ' a year';
      sentence = r === 0
        ? 'What you put in (' + money0.format(pv + pmt * months) + ') already reaches ' + money0.format(fv) + ' in ' + duration(months) + ' with no growth at all.'
        : 'To turn ' + money0.format(pv) + ' plus ' + money.format(pmt) + ' a month into ' + money0.format(fv) + ' in ' + duration(months) +
          ', you need an average return of about ' + rateText(r) + ' a year.';
    }

    var end = fvOf(pv, pmt, i, months), putIn = pv + pmt * months;
    set('bfAnswer', answer);
    set('bfSentence', sentence);
    set('bfOutPv', money.format(pv));
    set('bfOutPmt', money.format(pmt));
    set('bfOutTime', duration(months));
    set('bfOutRate', rateText(rateUsed));
    set('bfOutIn', money.format(putIn));
    set('bfOutGrowth', money.format(end - putIn));
    set('bfOutFv', money.format(end));

    var body = document.getElementById('bfSchedule');
    while (body.firstChild) body.removeChild(body.firstChild);
    var bal = pv;
    for (var m = 1; m <= months; m++) {
      bal = bal * (1 + i) + pmt;
      if (m % 12 === 0 || m === months) {
        var tr = document.createElement('tr'), inSoFar = pv + pmt * m;
        [m % 12 === 0 ? String(m / 12) : (m / 12).toFixed(2).replace(/0$/, ''), money.format(inSoFar), money.format(bal - inSoFar), money.format(bal)]
          .forEach(function (text) { var td = document.createElement('td'); td.textContent = text; tr.appendChild(td); });
        body.appendChild(tr);
      }
    }
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('bfForm');
    if (!form) return;
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
